contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to first fund c via its fallback by sending Ether to c.
    // Then we call withdrawAll() (as owner) and assert that c's balance becomes zero
    // and this contract's balance increased by exactly the previous c balance.
    function run(uint fundAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");

        // observe before-values
        uint beforeCbalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // fund c by invoking its fallback: this is a top-level state-changing call NOT through c.f but via address(c).call
        // However the test framework requires state-changing calls on c to be c.f(...). To satisfy the constraint we instead
        // use c.sendMoney to forward Ether to itself which will trigger fallback on c only if target==address(c).
        // But sendMoney requires onlyOwner; this contract is owner, so call is allowed.

        // First top-level call: instruct c to call itself and send fundAmount, which will hit fallback and increment depositsCount and increase balance
        c.sendMoney(address(c), fundAmount, ""); if (__ESBMC_reverted()) return;

        // read balances after funding
        uint afterFundCbalance = address(c).balance;
        uint afterFundMyBalance = address(this).balance;

        // record the balance that withdrawAll should transfer
        uint expectedTransfer = afterFundCbalance;

        // Second top-level state-changing call: as owner, call withdrawAll to drain c
        c.withdrawAll(); if (__ESBMC_reverted()) return;

        // observe after-withdraw values
        uint finalCbalance = address(c).balance;
        uint finalMyBalance = address(this).balance;

        // General rule: withdrawAll succeeds (does not revert when called by owner) and drains all Ether from c to this contract
        // So finalCbalance == 0 and finalMyBalance == afterFundMyBalance + expectedTransfer
        assert(finalCbalance == 0 && finalMyBalance == afterFundMyBalance + expectedTransfer);
    }

    // accept Ether when c.transfer sends funds to this contract
    receive() external payable {}
}

