// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 fundAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fundAmount);
        uint beforeCbalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;
        try c.sendMoney(address(c), fundAmount, "") {} catch { return; }
        uint afterFundCbalance = address(c).balance;
        uint afterFundMyBalance = address(this).balance;
        uint expectedTransfer = afterFundCbalance;
        try c.withdrawAll() {} catch { return; }
        uint finalCbalance = address(c).balance;
        uint finalMyBalance = address(this).balance;
        assertTrue(finalCbalance == 0 && finalMyBalance == afterFundMyBalance + expectedTransfer);
    }

    function testFuzz_run(uint256 fundAmount) public {
        _run(fundAmount);
    }

    receive() external payable {}
}
